"""Reviewed business descriptions for the course sales system.

Role names describe the project actors. Permission checks are implementation
details and do not create additional actors. Paths are checked when building.
"""
ROLES = [
 ('Hội viên', 'MEMBER', 'Đăng ký tài khoản; chọn và thanh toán khóa học; xem lịch, xin nghỉ, hủy/đổi khóa; xem nhận xét và kết quả; đánh giá khóa học.'),
 ('Huấn luyện viên', 'COACH', 'Xem lịch dạy và học viên được phân công; điểm danh, nhận xét từng buổi; quản lý hồ sơ cá nhân; lập và công bố tổng kết khóa học.'),
 ('Quản lí trung tâm', 'CENTER_MANAGER', 'Quản lý tài khoản, vai trò, tài nguyên, khóa học và cấu hình; xử lý đối soát, hoàn tiền; mở lại tổng kết, kiểm duyệt đánh giá và xem báo cáo.'),
 ('Lễ tân', 'RECEPTIONIST', 'Tạo và tra cứu hội viên; hỗ trợ đăng ký/hủy khóa và xin nghỉ; thu tiền mặt, xuất biên lai; ghi nhận check-in tại quầy.'),
]
ROLE_SOURCE = 'core/be/prisma/seed/roles.seed.js'
SCOPE = ('Hệ thống quản lý trung tâm thể thao phục vụ bốn vai trò: Hội viên, Huấn luyện viên, Quản lí trung tâm và Lễ tân. '
         'Sản phẩm kinh doanh là khóa học gồm nhiều buổi, có lịch học và học phí trọn khóa. Hội viên có thể đăng ký phần còn lại của khóa. '
         'Chức năng bán, gia hạn và bảo lưu gói tự tập đã ngừng sử dụng. Các dữ liệu gói và chứng từ cũ vẫn tồn tại trong cơ sở dữ liệu để tra cứu lịch sử. '
         'AI và kế hoạch tập luyện do AI sinh không thuộc phạm vi sản phẩm hiện hành.')
RULES = []


def rule(code, function, text, *sources):
    RULES.append(dict(id=code, function=function, text=text, sources=list(sources)))


rule('BR-01', 'Định danh tài khoản', 'Email và số điện thoại được chuẩn hóa và không được trùng tài khoản khác. Tự đăng ký online bắt buộc email, số điện thoại tùy chọn; tạo hội viên tại quầy bắt buộc số điện thoại, email tùy chọn. Tài khoản mới nhận vai trò mặc định trong cơ sở dữ liệu.', 'auth/auth.service.js', 'auth/auth.validation.js', 'member/member.validation.js', 'common/utils/account-contacts.js')
rule('BR-02', 'Đăng nhập', 'Mật khẩu đúng, tài khoản ACTIVE và email đã xác minh nếu có email mới được đăng nhập. Tài khoản chỉ có số điện thoại không cần xác minh email. Sai liên tiếp bị giới hạn theo cấu hình; thông báo sai thông tin không xác nhận tài khoản tồn tại.', 'auth/auth.service.js', 'auth/login-lock.service.js')
rule('BR-03', 'Quyền truy cập', 'Người dùng chỉ được thực hiện thao tác khi có quyền tương ứng và nằm trong phạm vi bản ghi cho phép. Bốn vai trò là các vai trò của đề tài; ma trận quyền được Quản lí trung tâm cấu hình, API đọc quyền từ cơ sở dữ liệu.', 'common/middlewares/authorize.middleware.js', 'permission/permission.service.js')
rule('BR-04', 'Đổi mật khẩu', 'Phải xác minh mật khẩu hiện tại khi đổi mật khẩu; mật khẩu mới phải khác mật khẩu hiện tại. Đổi hoặc đặt lại mật khẩu thu hồi hiệu lực token cũ bằng tokenVersion; token đặt lại phải hợp lệ và còn hạn.', 'auth/auth.service.js', 'auth/password-reset.service.js')
rule('BR-05', 'Tạo và thay đổi lịch', 'Huấn luyện viên phải đủ chuyên môn; loại phòng hỗ trợ bộ môn; lịch nằm trong khung hoạt động. Không được trùng phòng hoặc huấn luyện viên với buổi khác; sức chứa phải phù hợp tài nguyên. Đổi giờ phải báo trước ít nhất CLASS_RESCHEDULE_MIN_HOURS_BEFORE (mặc định 48 giờ, cấu hình không dưới 48), xét cả lịch cũ và mới; chặn xung đột của hội viên BOOKED và giữ chỗ PENDING_PAYMENT. Áp dụng cả đổi một buổi và sửa lịch tuần; sửa tên/giá không phải đổi giờ.', 'class/class-schedule.service.js', 'class/session-resource.service.js', 'class/class-reschedule-policy.service.js', 'class/class-schedule-change-policy.service.js')
rule('BR-06', 'Đăng ký khóa học', 'Hội viên phải ACTIVE, khóa OPEN và nằm trong cửa sổ đăng ký, còn buổi tương lai, không bị chặn đăng ký và không trùng lịch. Không yêu cầu mua gói tự tập. Tự đăng ký và Lễ tân đăng ký hộ áp dụng cùng điều kiện.', 'class/class-booking-policy.service.js', 'class/class-member-eligibility.service.js')
rule('BR-07', 'Sức chứa', 'Đăng ký BOOKED, giữ chỗ thanh toán còn hiệu lực và lời mời OFFERED còn hạn cùng chiếm sức chứa. Phép ghi đăng ký/giữ chỗ kiểm tra dưới khóa giao dịch để không bán vượt số chỗ.', 'class/class-member-eligibility.service.js', 'common/utils/schedule-transaction.js')
rule('BR-08', 'Học phí giữa khóa', 'Học phí = giá trọn khóa × số buổi SCHEDULED chưa bắt đầu / tổng số buổi không bị hủy, làm tròn tới 1.000 đồng gần nhất. Hóa đơn chốt giá, tổng buổi và số buổi mua tại thời điểm tạo; đổi giá khóa không sửa hóa đơn cũ.', 'cancellation/settlement.js', 'course-order/course-order.service.js')
rule('BR-09', 'Tạo đơn và quyền học', 'Khóa có học phí tạo hóa đơn COURSE/PENDING và đăng ký PENDING_PAYMENT. Chỉ xác nhận thanh toán hợp lệ mới chuyển BOOKED. Bấm lại cùng hội viên/khóa/kênh tái sử dụng hóa đơn đang chờ; giữ chỗ khác kênh bị từ chối.', 'course-order/course-order.service.js', 'course-order/course-hold.service.js')
rule('BR-10', 'Danh sách chờ', 'Chỉ tham gia khi hết chỗ nhưng đáp ứng các điều kiện khác; không tạo hóa đơn cho người đang WAITING. Mời theo joinedAt rồi ID; lời mời không vượt hạn đăng ký. Khóa không OPEN hoặc hết hạn đăng ký thì hủy lượt chờ/lời mời còn hiệu lực.', 'class/class-waitlist.service.js', 'course-order/course-order.service.js')
rule('BR-11', 'Hạn thanh toán', 'Hóa đơn khóa học có hạn thanh toán. COURSE/ONLINE có thêm khoảng chờ webhook theo PAYMENT_WEBHOOK_GRACE_SECONDS; khoảng chờ không kéo dài thời gian khách được chuyển tiền. COURSE/COUNTER không có khoảng chờ ngân hàng.', 'payment/course-payment-window.service.js', 'payment/invoice-create.service.js')
rule('BR-12', 'Webhook thanh toán', 'Webhook phải qua xác thực SePay; cùng ID giao dịch không ghi tiền lần hai. Chỉ nhận một mã hóa đơn có tiền tố cấu hình; nếu code do SePay trích không phù hợp thì tìm trong nội dung ngân hàng; nhiều mã khác nhau cần đối soát. Đủ tổng tiền và giữ chỗ/lịch hợp lệ mới tự chốt. Sau deadline, chỉ xét tiền có bằng chứng ngân hàng trước hạn và webhook tới trước holdReleaseAt; thiếu độ chính xác tại giây ranh giới thì đối soát.', 'payment/sepay-webhook.service.js', 'payment/sepay-course-policy.service.js', 'payment/course-payment-window.service.js')
rule('BR-13', 'Chuyển thiếu hoặc thừa', 'Các giao dịch khác ID cùng hóa đơn được cộng dồn. Tổng đúng số tiền mới tự thanh toán; chuyển thiếu không kéo hạn khóa học thêm 48 giờ. Chuyển thừa phải được duyệt; phiếu thiếu được khép khi đã bù, phần thừa có phiếu riêng.', 'payment/payment-apply.service.js', 'payment/payment-case-closure.service.js')
rule('BR-14', 'Hết hạn giữ chỗ', 'Qua mốc nhả chỗ, hóa đơn COURSE còn PENDING chuyển FAILED và giữ chỗ được hủy. Tiền đã nhận vẫn được giữ để xử lý đối soát/hoàn. Tiền đến muộn không tự phục hồi chỗ hoặc lấy chỗ của người khác.', 'payment/invoice-expiry.job.js', 'course-order/course-hold-policy.service.js')
rule('BR-15', 'Thu tiền mặt', 'Lễ tân thu đủ số còn lại của hóa đơn COUNTER còn hợp lệ. Hóa đơn ONLINE đã nhận một phần cũng được nộp bù phần thiếu bằng tiền mặt; ONLINE chưa nhận tiền không được thu tiền mặt theo luồng này. Server chốt thời điểm sau khi lấy khóa. Yêu cầu chờ khóa qua hạn bị từ chối; thanh toán được ghi cùng việc xác nhận quyền học. Khách chuyển khoản dùng kênh ONLINE.', 'payment/payment.service.js', 'payment/payment-apply.service.js')
rule('BR-16', 'Khai báo đã chuyển', 'Chỉ chủ hóa đơn được khai báo trong cửa sổ cho phép, khi hóa đơn PENDING hoặc FAILED. Mỗi hóa đơn chỉ có một MEMBER_CLAIM đang mở; khai báo không tự làm hóa đơn PAID hoặc gia hạn giữ chỗ.', 'reconciliation/payment-claim.service.js')
rule('BR-17', 'Đối soát', 'Giao dịch chỉ được gán tiền một lần. Phải kiểm tra chứng cứ, hóa đơn và điều kiện chốt; khoản đã có yêu cầu hoàn không được dùng lại. Chuyển lặp khác ID sau PAID là khoản cần xử lý riêng, không tự cấp thêm quyền học.', 'reconciliation/reconciliation-resolve.service.js', 'reconciliation/reconciliation-case.service.js')
rule('BR-18', 'Hủy khóa của hội viên', 'Chỉ hủy/đổi đăng ký BOOKED có hóa đơn và còn buổi tương lai; không có yêu cầu đổi đang chờ. Giá trị còn lại tính từ giá trị lần mua và số buổi đã mua, chỉ hoàn buổi chưa diễn ra. Trước buổi đã mua đầu tiên không phí; sau đó trừ phí theo cấu hình. Buổi tự vắng không được hoàn như buổi chưa học.', 'cancellation/purchase-value.service.js', 'cancellation/settlement.js')
rule('BR-19', 'Yêu cầu hoàn tiền', 'Phần hoàn dương khi hủy/đổi khóa tạo Refund PENDING và mã tra cứu HT. Quản lí trung tâm chuyển trả bên ngoài hệ thống rồi nhập tham chiếu để DONE. Tạo yêu cầu không có nghĩa đã trả tiền; hủy khóa không cộng vào ví.', 'cancellation/payout.service.js', 'reconciliation/refund.service.js', 'reconciliation/refund-reference.js')
rule('BR-20', 'Trung tâm hủy khóa/buổi', 'Hủy cả khóa hoàn giá trị các buổi chưa học, không thu phí hủy; hủy một buổi tạo yêu cầu hoàn giá trị một buổi cho đăng ký đã trả tiền. Giữ dữ liệu học/chứng từ cũ và thông báo người bị ảnh hưởng.', 'cancellation/center-cancel.service.js', 'class/class-session.service.js')
rule('BR-21', 'Đổi khóa học', 'Chuyển đăng ký cả khóa, không phải học bù một buổi. Khóa đích khác nguồn, cùng bộ môn, còn nhận đăng ký, còn chỗ và không trùng lịch hội viên ngoài khóa đang rời. Kiểm tra lại nguồn/chỗ đích, lịch và hạn hóa đơn chênh lệch khi chốt đổi. Đối chiếu giá trị chưa dùng của nguồn với học phí còn lại của khóa đích. Chênh lệch dương tạo hóa đơn ADJUSTMENT và giữ chỗ đích, quyền cũ còn tới khi đổi hoàn tất. Chênh lệch không dương hoàn tất ngay; phần phải trả lại đi qua REFUND.', 'purchase-change/purchase-change-request.service.js', 'purchase-change/purchase-target.service.js', 'purchase-change/purchase-change.service.js', 'purchase-change/course-change-policy.service.js')
rule('BR-22', 'Xin nghỉ từng buổi', 'Đăng ký BOOKED mới được báo nghỉ trước hạn backend tính; ghi EXCUSED, không hủy cả khóa và không phát sinh tiền hoàn. Có thể hủy báo nghỉ trước khi buổi bắt đầu. EXCUSED không được ghi đè thành ABSENT khi điểm danh.', 'attendance/attendance-excuse.service.js', 'attendance/attendance.service.js')
rule('BR-23', 'Check-in', 'Lễ tân ghi lượt đến cho hội viên ACTIVE. Nếu chưa có BOOKED trong khóa OPEN/CLOSED thì lưu cảnh báo nhưng vẫn ghi check-in. Check-in không thay thế điểm danh và không cấp quyền học.', 'attendance/attendance.service.js')
rule('BR-24', 'Điểm danh', 'Huấn luyện viên chỉ ghi buổi mình phụ trách; Quản lí trung tâm thao tác theo quyền quản lý điểm danh. Buổi phải đã bắt đầu, chưa hủy và chưa kết thúc; sau khi kết thúc phải được mở hạn sửa. Học viên phải thuộc phạm vi đăng ký tại buổi đó hoặc có điểm danh lịch sử hợp lệ.', 'attendance/attendance.service.js', 'common/utils/session-access.js')
rule('BR-25', 'Nhận xét từng buổi', 'Huấn luyện viên phụ trách buổi hoặc Quản lí trung tâm được ghi sau khi buổi bắt đầu, kể cả sau giờ kết thúc, nếu buổi/khóa chưa hủy. Có điểm 1–5 hoặc ghi chú, tối đa 2.000 ký tự; expectedVersion tránh ghi đè. Nhận xét không đổi điểm danh.', 'session-feedback/session-feedback.service.js', 'session-feedback/session-feedback.validation.js')
rule('BR-26', 'Lịch sử học tập', 'Hội viên chỉ xem lịch sử của mình; Quản lí trung tâm xem hội viên theo quyền attendance.manage. Danh sách gồm mọi buổi của khóa, ghép điểm danh/nhận xét đúng sessionId và memberId. Chưa có kết quả không tự coi là vắng; hủy/mua lại giữ snapshot lịch sử.', 'course-history/course-history.service.js', 'course-history/course-history.routes.js', 'cancellation-history/cancellation-history.service.js')
rule('BR-27', 'Chặn do vắng mặt', 'Chỉ ABSENT của buổi đã kết thúc, không hủy và chưa đổi lịch mới được tính theo ngưỡng/cửa sổ cấu hình. Sửa điểm danh có thể giảm/gỡ chặn. Gỡ thủ công phải có quyền, lý do và audit.', 'attendance/no-show.service.js')
rule('BR-28', 'Hồ sơ huấn luyện viên', 'Email liên hệ công khai là trường riêng, có thể trùng email đăng nhập; chỉ hiện liên hệ khi bật showContact. Danh bạ chỉ hiển thị tài khoản ACTIVE có quyền xem lịch dạy và ít nhất một bộ môn chuyên môn đang hoạt động.', 'profile/profile.mapper.js', 'profile/coach-directory.service.js')
rule('BR-29', 'Hồ sơ học viên', 'Huấn luyện viên chỉ xem học viên trong phạm vi buổi thực dạy và thời gian xem cho phép. Khóa đã hủy không cấp phạm vi. Tắt shareWithCoach thì không trả trainingProfile; không trả dữ liệu tài chính trong hồ sơ dành cho huấn luyện viên.', 'profile/coach-member-scope.service.js', 'profile/coach-members.service.js')
rule('BR-30', 'Kết thúc khóa', 'Chỉ khóa OPEN/CLOSED có ít nhất một buổi không hủy, với mọi buổi không hủy đã kết thúc, mới chuyển COMPLETED. Tổng kết lấy học viên có đăng ký tại thời điểm buổi cuối kết thúc; người hủy sau thời điểm đó vẫn được tính. Job chạy theo chu kỳ server, không phải lịch chạy hằng ngày.', 'course-summary/course-completion.job.js')
rule('BR-31', 'Chuyên cần', 'Tính trên buổi đã kết thúc, không hủy, bắt đầu từ mốc đăng ký: PRESENT / (tổng buổi đủ điều kiện − EXCUSED) × 100. Chưa điểm danh nằm trong mẫu số và được đếm missing; mẫu số 0 trả 0.', 'course-summary/course-attendance.service.js')
rule('BR-32', 'Tổng kết khóa', 'Huấn luyện viên được phân công tổng kết sửa khi DRAFT; khác kết quả gợi ý phải có nhận xét. Công bố yêu cầu mọi học viên có kết quả và tiến bộ, xác nhận nếu thiếu điểm danh; lưu snapshot và tăng revision. Quản lí trung tâm mở lại phải có lý do.', 'course-summary/course-summary.service.js')
rule('BR-33', 'Đánh giá khóa', 'Học viên có item tổng kết mới được đánh giá, không cần đợi tổng kết PUBLISHED. Mỗi học viên một đánh giá mỗi khóa; cửa sổ tính từ buổi cuối không hủy. Huấn luyện viên/hội viên thấy tên viết tắt; kiểm duyệt ẩn nhận xét nhưng giữ điểm sao.', 'course-summary/course-rating.service.js')
rule('BR-34', 'Báo cáo doanh thu', 'Thu ghi theo paidAt của hóa đơn đã thanh toán/đã hoàn, trừ tiền CREDIT để không tính hai lần. Hoàn doanh thu chỉ lấy Refund DONE không gắn caseId, thuộc hóa đơn có paidAt, giới hạn theo giá trị thu còn lại. Thuần = thu − hoàn được ghi nhận; khoản hoàn tiền chưa gán không tự làm giảm doanh thu khóa.', 'report/report-finance.service.js')
rule('BR-35', 'Kỳ báo cáo', 'Dùng múi giờ Việt Nam, tuần bắt đầu thứ Hai; kỳ trước có cùng số ngày. Giá trị kỳ trước bằng 0 trả null cho tỷ lệ thay đổi. Mỗi chiều cơ cấu có nhóm khác/chênh lệch để khớp tổng thuần; giới hạn khoảng lấy từ cấu hình.', 'report/report-periods.js', 'report/report-breakdown.service.js')
rule('BR-36', 'Báo cáo hội viên và tổng kết', 'Báo cáo hội viên theo kỳ có hội viên mới, khóa có lịch trong kỳ, đăng ký mới/hủy, chỗ và tỷ lệ lấp đầy; không dùng giữ chỗ PENDING_PAYMENT như đăng ký chính thức khi tính lấp đầy. Báo cáo tổng kết dùng quyền riêng và cùng builder với file xuất.', 'report/report-member.service.js', 'course-summary/course-report.service.js')
BY_RULE = {r['id']: r for r in RULES}
